import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0020 — Prestazioni: indicizzazione a batch, cache dei candidati di ricerca, albero virtualizzato (M7-WP1)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0020-performance-details.md","filePath":"adr/0020-performance-details.md"}'),d={name:"adr/0020-performance-details.md"};function l(n,e,r,c,s,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0020-—-prestazioni-indicizzazione-a-batch-cache-dei-candidati-di-ricerca-albero-virtualizzato-m7-wp1" tabindex="-1">ADR-0020 — Prestazioni: indicizzazione a batch, cache dei candidati di ricerca, albero virtualizzato (M7-WP1) <a class="header-anchor" href="#adr-0020-—-prestazioni-indicizzazione-a-batch-cache-dei-candidati-di-ricerca-albero-virtualizzato-m7-wp1" aria-label="Permalink to &quot;ADR-0020 — Prestazioni: indicizzazione a batch, cache dei candidati di ricerca, albero virtualizzato (M7-WP1)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.4, §4.4, Appendice A, C.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-27</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>Appendice A (prestazioni client, indicizzazione, cloud), §2.4 ricerca; D-06</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Su un vault sintetico da 50.000 note (168 MB, <code>apps/desktop/internal/perf</code>) il profilo CPU mostrava tre problemi: l&#39;indicizzazione iniziale non finiva in tempo utile (un commit WAL per nota, flush di FTS5 a ogni statement, risoluzione dei link di tutto il vault a ogni salvataggio), la ricerca leggeva ogni corpo con una query separata (un lock di lettura WAL per file) e l&#39;albero dei file montava un nodo DOM per ogni voce. Misure e metodo in <code>docs/perf/README.md</code>.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><strong>Indexer</strong> (<code>internal/indexer</code>): <code>Full</code> legge e analizza i file con un pool di worker e li scrive in transazioni da al massimo 250 note o 16 MB; statement preparati per transazione; le righe FTS di un batch si scrivono dopo tutte le altre tabelle (dopo la prima scrittura FTS5 ogni statement con foreign key provoca un flush del segmento). Un batch fallito si riprova nota per nota (una riga cattiva non perde le altre). <code>Update</code> risolve i link solo della nota modificata con un resolver in cache (<code>links.ResolvePaths</code>); la risoluzione completa resta quando cambia l&#39;insieme dei file o degli alias.</li><li><strong>Ricerca</strong> (<code>internal/search</code>): cache dei candidati per database (<code>cache.go</code>): elenco file, titolo, corpo e tag in memoria, ordinati per path, ricaricati in modo incrementale (impronta <code>count/max(indexed_at)/somma dimensioni</code> e confronto per riga <code>(id, indexed_at)</code>); valutazione parallela sui core con lo stesso <code>eval</code> di prima, quindi stessi risultati e stesso ordine. Budget di default 512 MB di testo (<code>DefaultCacheBudget</code>): oltre, si torna allo streaming da SQLite in una sola transazione di lettura (comunque molto più veloce del vecchio N+1). <code>Warm</code> carica la cache in background dopo il primo indice; <code>Forget</code> la libera alla chiusura del vault. <code>matchBody</code> taglia la riga dello snippet dal corpo invece di abbassare e provare ogni riga.</li><li><strong>Albero dei file</strong>: righe di altezza fissa (24 px) e finestra di rendering (<code>flattenTree</code> + overscan); nessuna dipendenza nuova.</li><li><strong>Misura</strong>: dataset deterministici (<code>internal/perf/dataset</code>), suite <code>TestPerf</code> (<code>make perf</code>), <code>perfcheck</code> contro baseline JSON in <code>docs/perf/</code>, esecuzione manuale (il workflow <code>nightly-perf.yml</code> è stato rimosso il 2026-10-30), spec Playwright <code>ui-perf.spec.ts</code>, load test cloud (<code>TestServeLoadEnv</code> solo test + k6).</li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Tabella FTS5 <code>contentless</code>/external content</strong>: dimezzerebbe <code>index.db</code> (894 MB per 168 MB di note) ma richiede una migrazione dello schema e di ogni query che legge <code>fts_content</code>; rimandata.</li><li><strong>Cache dei corpi in minuscolo</strong>: elimina <code>ToLower</code> per query ma raddoppia la RAM; scartata finché la ricerca è sotto i 200 ms.</li><li><strong>Libreria di virtualizzazione (<code>react-virtual</code>)</strong>: non necessaria per una lista a righe fisse.</li><li><strong>Segnale di invalidazione dall&#39;indexer alla cache</strong>: meno query ma accoppia i pacchetti; l&#39;impronta costa pochi ms.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>La cache tiene in RAM circa il testo del vault (≈ 210 MB heap a 50k note); è il costo dichiarato della ricerca &lt; 200 ms. Per vault oltre il budget la ricerca resta corretta ma più lenta.</li><li>Le regex su tutto il vault (≈ 0,45 s a 50k) non rispettano i 200 ms: servirebbe un prefiltro con i letterali della regex.</li><li><code>index.db</code> è ≈ 5,3 volte il testo (trigram): da rivedere se la dimensione disco diventa un problema.</li><li>Il test <code>TestQueryEquivalentToLegacy</code> conserva la strategia precedente come riferimento: eliminarlo solo se si rimuove la modalità streaming. Differenza nota: &quot;nessun risultato&quot; ora è <code>[]</code> e non <code>null</code>.</li></ul><h2 id="revisione-2026-10-29-—-budget-del-bundle-web-ui-con-il-workbench-m9-wp0-adr-0029" tabindex="-1">Revisione 2026-10-29 — Budget del bundle Web UI con il workbench (M9-WP0, ADR-0029) <a class="header-anchor" href="#revisione-2026-10-29-—-budget-del-bundle-web-ui-con-il-workbench-m9-wp0-adr-0029" aria-label="Permalink to &quot;Revisione 2026-10-29 — Budget del bundle Web UI con il workbench (M9-WP0, ADR-0029)&quot;">​</a></h2><p>Il budget della Web UI (<code>BUDGET</code> in <code>web/scripts/esbuild.mjs</code>: iniziale ≤ 700 kB, totale ≤ 1000 kB, ADR-0025) valeva per un&#39;app di sola console. Il workbench del vault (ADR-0029) porta nella Web UI tutto il frontend desktop (Excalidraw, mermaid, pdfjs, mathjax) e il core Go in WebAssembly (ADR-0030). Applicare un solo limite a tutto alzerebbe il limite della console o renderebbe impossibile il workbench. Il budget si divide quindi in tre parti, misurate e verificate dalla build (<code>checkBudget</code>) in M9-WP5:</p><table tabindex="0"><thead><tr><th>Parte</th><th>Cosa si misura</th><th>Limite</th></tr></thead><tbody><tr><td><strong>Console</strong> (entry <code>src/main.tsx</code>)</td><td>iniziale: entry e import statici; totale: tutti i chunk <strong>esclusi</strong> quelli raggiungibili solo dall&#39;import dinamico del workbench</td><td>invariato: iniziale ≤ 700 kB, totale ≤ 1000 kB</td></tr><tr><td><strong>Workbench JS</strong> (pagina <code>workbench.html</code> e worker)</td><td>iniziale: il chunk d&#39;ingresso e i suoi import statici, <strong>CSS compreso</strong>; totale: tutto ciò che l&#39;ingresso e il worker raggiungono</td><td>iniziale ≤ 2500 kB, totale ≤ 23000 kB</td></tr><tr><td><strong>Workbench WASM</strong> (<code>memobrain-core.wasm</code>, <code>sqlite3.wasm</code>)</td><td>dimensione compressa con gzip (come viene servita)</td><td>core ≤ 8 MB (obiettivo dello spike, ADR-0030); sqlite ≤ 1,5 MB</td></tr></tbody></table><p>Regole:</p><ul><li>La console non deve importare staticamente nessun modulo di <code>@memobrain/workbench</code>. Un test della build verifica che il chunk iniziale della console non contenga moduli del pacchetto.</li><li>Il limite del workbench JS segue quello del desktop, perché il codice è lo stesso: se il desktop alza il proprio limite di proposito, il web lo segue nella stessa modifica.</li><li>Il limite del WASM è un obiettivo dello spike M9-WP1. Se lo spike lo supera, si ridiscute qui con le misure, invece di alzarlo in silenzio.</li></ul><h3 id="misura-del-core-webassembly-w8-lotto-c2-2026-11-01" tabindex="-1">Misura del core WebAssembly (W8 lotto C2, 2026-11-01) <a class="header-anchor" href="#misura-del-core-webassembly-w8-lotto-c2-2026-11-01" aria-label="Permalink to &quot;Misura del core WebAssembly (W8 lotto C2, 2026-11-01)&quot;">​</a></h3><p>Il 1° novembre il core (<code>task wasm-core</code>, <code>-trimpath -ldflags &quot;-s -w&quot;</code>) pesava 39,2 MB non compresso e 8090 kB con <code>gzip -9</code>, meno del 2% sotto il limite. Misura per pacchetto (dimensione del codice delle funzioni, dalla sezione <code>name</code> di una build senza <code>-s</code>, compressa per gruppo): la parte più grande evitabile era <strong>gRPC con protobuf</strong> (circa 680 kB gzip di solo codice, più descrittori e tabelle nella sezione dati), portato da <code>apps/desktop/internal/sync/transport</code> per il canale di notifica. Nel browser gRPC non può connettersi (il <code>net</code> di <code>js/wasm</code> non apre socket TCP): il client provava due volte e poi passava a SSE.</p><p>Decisione: il client gRPC è in <code>notify_grpc.go</code> (<code>//go:build !js</code>); nel core WebAssembly <code>notify_js.go</code> dichiara <code>grpcSupported = false</code> e le notifiche usano solo SSE, come già accadeva di fatto dopo i due tentativi falliti. Con gRPC escono dal binario anche <code>memobrain/shared/notifyv1</code>, protobuf, <code>golang.org/x/net/trace</code>, <code>html/template</code> e <code>net/http/httputil</code>. Il comportamento del desktop non cambia.</p><table tabindex="0"><thead><tr><th>Build del core</th><th>Non compresso</th><th>gzip -9</th></tr></thead><tbody><tr><td>prima (con gRPC)</td><td>39,2 MB</td><td>8090 kB</td></tr><tr><td>dopo (<code>notify_grpc.go</code> solo nativo)</td><td>30,7 MB</td><td>6751 kB</td></tr></tbody></table><p>Il limite di 8192 kB resta invariato. Candidati successivi, se servisse altro margine: il client OIDC del desktop (<code>go-oidc</code>, <code>go-jose</code>, <code>oauth2</code>, circa 105 kB gzip di codice: nel browser il token arriva dalla pagina) e <code>goose</code> con <code>text/template</code> per le migrazioni di <code>internal/store</code> (circa 60 kB). Entrambi richiedono di separare il codice nativo dietro build tag in pacchetti con più chiamanti.</p><h2 id="revisione-2026-11-16-—-budget-iniziale-della-console-a-720-kb-m21-adr-0061" tabindex="-1">Revisione 2026-11-16 — Budget iniziale della console a 720 kB (M21, ADR-0061) <a class="header-anchor" href="#revisione-2026-11-16-—-budget-iniziale-della-console-a-720-kb-m21-adr-0061" aria-label="Permalink to &quot;Revisione 2026-11-16 — Budget iniziale della console a 720 kB (M21, ADR-0061)&quot;">​</a></h2><p><a href="./0061-budget-iniziale-console-720.html">ADR-0061</a>, accettata il 2026-11-16 per decisione dell&#39;owner, porta il limite <strong>iniziale della console</strong> da 700 a <strong>720 kB</strong> (<code>BUDGET.console.initialKB</code> in <code>web/scripts/esbuild.mjs</code>): con le aggiunte di M21 la console pesa 701 kB. Il totale (1000 kB), il budget del workbench e quelli del WASM non cambiano, e la console resta un file unico coperto da SRI. Nella tabella «Console» sopra, il limite iniziale vale ora <strong>≤ 720 kB</strong>; il testo della revisione del 2026-10-29 resta lo storico.</p>',22)])])}const g=o(d,[["render",l]]);export{m as __pageData,g as default};
